  const formatDate = (value: string) => new Intl.DateTimeFormat(isEs ? 'es-ES' : isEs ? 'es-ES' : isEn ? 'en' : 'id', { day: 'numeric', month: 'long', year: 'numeric', timeZone: 'UTC' }).format(new Date(value + 'T00:00:00Z'));
